{
  "headline": "FDA's shortage list shows methotrexate injection on allocation since 2023-03-13 with multiple manufacturers reporting current shortages and estimated recovery in October 2026",
  "headline_cites": ["E34", "E29", "E30", "E31", "E32", "E33"],
  "sentences": [
    {
      "text": "FDA first posted the methotrexate sodium injection shortage on 2023-03-13 and it remains current as of 2026-10-17.",
      "cites": ["E34"]
    },
    {
      "text": "As of 2026-10-21 the shortage has been on FDA's list for 43 months.",
      "cites": ["D9"]
    },
    {
      "text": "Accord Healthcare Inc., Fresenius Kabi USA LLC, Hikma Pharmaceuticals USA Inc., Hospira Inc. (a Pfizer Company), and Teva Pharmaceuticals USA Inc. all show current shortage status with various package NDCs.",
      "cites": ["E29", "E30", "E31", "E32", "E33"]
    },
    {
      "text": "Hikma Pharmaceuticals USA Inc. indicates additional lots will be available in the October 2026 timeframe.",
      "cites": ["E31"]
    },
    {
      "text": "Teva Pharmaceuticals USA Inc. estimates recovery in October 2026.",
      "cites": ["E33"]
    },
    {
      "text": "Fresenius Kabi USA LLC advises checking wholesaler for inventory.",
      "cites": ["E30"]
    },
    {
      "text": "Corvale East, General, and Lakeside hospitals hold 16-19 days of supply at current usage rates.",
      "cites": ["D1", "D2", "D3"]
    }
  ]
}
